    verticaltiki: {ds:-6,  as:6,  ceil:2.0, floor:-1.5, bias:0.15},
    wingplay:     {ds:-5,  as:5,  ceil:2.0, floor:-1.2, bias:0.2},
    lanuestra:    {ds:-14, as:11, ceil:2.3, floor:-1.0, bias:0.2},
    secondball:   {ds:-3,  as:6,  ceil:2.0, floor:-1.5, bias:0.05},
