  const diff=(s.score[0]+(s.startScore?.[0]||0))-(s.score[1]+(s.startScore?.[1]||0)), rem=s.minute<=90?90-s.minute:120-s.minute;
  const sDef=(s.startScore?.[0]||0)-(s.startScore?.[1]||0);
